import React from 'react';
import Navigation from './Navigation';

const Layout = ({ children }) => {
  return (
    <div style={{ minHeight: '100vh', backgroundColor: '#f5f5f5' }}>
      <Navigation />
      <main style={{ padding: '20px' }}>
        {children}
      </main>
    </div>
  );
};

export default Layout;
